function unit(idSuffix, name, { factionId, originGroupId, entryId, cardType, rarity = 'common', power, row, ability, effect = null, evolution = null, artwork = null, artworkCentered = false, artworkFill = false, artworkZoomedOut = false, artworkHalfBody = false, metadata = {}, ...rest }) {
  return {
    id: `${factionId}-${idSuffix}`,
    name,
    factionId,
    originGroupId,
    residentEvilEntryId: entryId,
    cardType,
    rarity,
    power,
    row,
    ability,
    effect,
    evolution,
    artwork,
    artworkCentered,
    artworkFill,
    artworkZoomedOut,
    artworkHalfBody,
    metadata,
    ...rest,
  }
}

