export const cards = rawCards.map((card) => {
  const originGroupId = originMigration[card.originGroupId] ?? card.originGroupId
  const organizationId = organizationByOrigin[originGroupId]
  return {
    ...card,
    organizationId,
    factionId: factionByOrganization[organizationId],
    originGroupId,
    metadata: { ...card.metadata, ...(prototypeOriginalIds.has(card.id) ? { canonStatus: 'prototype-original' } : {}), ...(loreNotes[card.id] ? { loreAffiliation: loreNotes[card.id] } : {}) },
  }
})

const catalogErrors = validateCatalog({ factions, organizations, origins, entries, cardTypes, leaders, cards })
if (catalogErrors.length > 0) throw new Error(`Invalid catalog: ${catalogErrors.join(' ')}`)

export { cardTypes, entries, factions, leaders, organizations, origins }
